   692→// Select evenly-spaced key frames from a larger set
   693→function selectKeyFrames(frames, count) {
   694→  const result = [];
   695→  const step = (frames.length - 1) / (count - 1);
   696→  for (let i = 0; i < count; i++) {
   697→    result.push(frames[Math.round(i * step)]);
   698→  }
   699→  return result;
   700→}
