   702→// Analyze speech transcription for communication quality
   703→function analyzeSpeechPatterns(transcription, durationSeconds) {
   704→  const words = transcription.trim().split(/\s+/).filter(w => w.length > 0);
   705→  const wordCount = words.length;
   706→  const wpm = durationSeconds > 0 ? Math.round((wordCount / durationSeconds) * 60) : 0;
   707→
   708→  // Filler word detection
   709→  const fillerWords = ['um', 'uh', 'like', 'you know', 'so', 'basically', 'actually', 'literally', 'right', 'okay so', 'i mean'];
   710→  const fillerCounts = {};
   711→  let totalFillers = 0;
   712→  const lowerTranscription = transcription.toLowerCase();
   713→
   714→  for (const filler of fillerWords) {
   715→    const regex = new RegExp(`\\b${filler}\\b`, 'gi');
   716→    const matches = lowerTranscription.match(regex);
   717→    if (matches && matches.length > 0) {
   718→      fillerCounts[filler] = matches.length;
   719→      totalFillers += matches.length;
   720→    }
   721→  }
   722→
   723→  const fillerRate = wordCount > 0 ? (totalFillers / wordCount) * 100 : 0;
   724→
   725→  // Pace analysis
   726→  let paceAssessment = 'good';
   727→  let paceFeedback = '';
   728→  if (wpm < 100) {
   729→    paceAssessment = 'too_slow';
   730→    paceFeedback = 'Your speaking pace is quite slow. Try to speak more naturally and with more energy. Aim for 120-150 words per minute.';
   731→  } else if (wpm < 120) {
   732→    paceAssessment = 'slightly_slow';
   733→    paceFeedback = 'Your pace is a bit slow. Try to increase your speaking speed slightly for more engaging delivery.';
   734→  } else if (wpm <= 160) {
   735→    paceAssessment = 'good';
   736→    paceFeedback = 'Your speaking pace is natural and easy to follow. Well done!';
   737→  } else if (wpm <= 180) {
   738→    paceAssessment = 'slightly_fast';
   739→    paceFeedback = 'You\'re speaking a bit quickly. Try to slow down slightly and pause between key points.';
   740→  } else {
   741→    paceAssessment = 'too_fast';
   742→    paceFeedback = 'You\'re speaking too fast — this can signal nervousness. Take deliberate pauses between sentences and breathe.';
   743→  }
   744→
   745→  // Sentence structure analysis
   746→  const sentences = transcription.split(/[.!?]+/).filter(s => s.trim().length > 0);
   747→  const avgSentenceLength = sentences.length > 0 ? Math.round(wordCount / sentences.length) : 0;
   748→
   749→  // Communication score (1-10)
   750→  let communicationScore = 7;
   751→  // Penalize for filler words
   752→  if (fillerRate > 5) communicationScore -= 2;
   753→  else if (fillerRate > 3) communicationScore -= 1;
   754→  // Penalize for bad pace
   755→  if (paceAssessment === 'too_slow' || paceAssessment === 'too_fast') communicationScore -= 1.5;
   756→  else if (paceAssessment === 'slightly_slow' || paceAssessment === 'slightly_fast') communicationScore -= 0.5;
   757→  // Reward for good sentence structure
   758→  if (avgSentenceLength >= 10 && avgSentenceLength <= 25) communicationScore += 0.5;
   759→  // Penalize for very short responses
   760→  if (wordCount < 50) communicationScore -= 2;
   761→  else if (wordCount < 100) communicationScore -= 1;
   762→  // Reward for substantial responses
   763→  if (wordCount >= 150 && wordCount <= 400) communicationScore += 0.5;
   764→
   765→  communicationScore = Math.max(1, Math.min(10, Math.round(communicationScore * 10) / 10));
   766→
   767→  return {
   768→    word_count: wordCount,
   769→    duration_seconds: durationSeconds,
   770→    words_per_minute: wpm,
   771→    filler_words: fillerCounts,
   772→    total_fillers: totalFillers,
   773→    filler_rate: Math.round(fillerRate * 10) / 10,
   774→    pace: {
   775→      assessment: paceAssessment,
   776→      wpm,
   777→      feedback: paceFeedback
   778→    },
   779→    sentence_count: sentences.length,
   780→    avg_sentence_length: avgSentenceLength,
   781→    communication_score: communicationScore,
   782→    tips: generateSpeechTips(fillerRate, wpm, wordCount, totalFillers, fillerCounts)
   783→  };
   784→}
   785→
   786→function generateSpeechTips(fillerRate, wpm, wordCount, totalFillers, fillerCounts) {
   787→  const tips = [];
   788→
   789→  if (fillerRate > 3) {
   790→    const topFillers = Object.entries(fillerCounts)
   791→      .sort((a, b) => b[1] - a[1])
   792→      .slice(0, 3)
   793→      .map(([word, count]) => `"${word}" (${count}x)`);
   794→    tips.push(`Reduce filler words — you used ${totalFillers} fillers: ${topFillers.join(', ')}. Try pausing silently instead.`);
   795→  }
   796→
   797→  if (wpm > 160) {
   798→    tips.push('Slow down your pace. Take a breath between key points to let your message land.');
   799→  } else if (wpm < 110) {
   800→    tips.push('Pick up the pace slightly. A faster tempo projects confidence and engagement.');
   801→  }
   802→
   803→  if (wordCount < 80) {
   804→    tips.push('Your response was quite short. Aim for 1-2 minutes of speaking time to give a comprehensive answer.');
   805→  }
   806→
   807→  if (tips.length === 0) {
   808→    tips.push('Strong verbal delivery! Your pace and clarity are good. Keep practicing to maintain consistency.');
   809→  }
   810→
   811→  return tips;
   812→}
