   970→  }
   971→
   972→  // Extract results with fallbacks for any failed analyses
   973→  // BUG FIX: Use helper function with multiple safety layers to prevent null crashes.
   974→  // Previous null checks still let through edge cases where AI returned non-null truthy values
   975→  // that were missing expected fields, causing TypeError: Cannot read properties of null.
   976→  function safeExtract(index, fallback) {
   977→    try {
   978→      const s = settled[index];
