  1012→
  1013→  // Algorithmic speech analysis (always works — no AI calls)
  1014→  const speechAnalysis = analyzeSpeechPatterns(finalTranscription, durationSeconds);
  1015→
  1016→  // BUG FIX: Wrap result assembly in try/catch — if ANY field access crashes, return a safe default
  1017→  try {
