  1154→// AI interviewer conducts a conversational interview turn
  1155→async function conductInterviewTurn(conversation, baseQuestions, currentQuestionIndex, targetRole, options = {}) {
  1156→  // Send last 12 turns for better context on follow-ups
  1157→  const recentConvo = conversation.slice(-12);
  1158→  const convoText = recentConvo.map(turn => {
  1159→    if (turn.role === 'interviewer') return `INTERVIEWER: ${turn.text}`;
  1160→    return `CANDIDATE: ${turn.text}`;
  1161→  }).join('\n\n');
  1162→
  1163→  const candidateTurnCount = conversation.filter(t => t.role === 'candidate').length;
  1164→  const followUpCount = conversation.filter(t => t.role === 'interviewer' && (t.action === 'follow_up' || t.action === 'challenge')).length;
  1165→  const remainingQuestions = baseQuestions.slice(currentQuestionIndex);
  1166→  const nextPlannedQuestion = remainingQuestions.length > 0
  1167→    ? remainingQuestions[0].question_text
  1168→    : null;
  1169→
  1170→  // Count consecutive follow-ups on the current topic
  1171→  let consecutiveFollowUps = 0;
  1172→  for (let i = conversation.length - 1; i >= 0; i--) {
  1173→    const t = conversation[i];
  1174→    if (t.role === 'interviewer' && (t.action === 'follow_up' || t.action === 'challenge')) {
  1175→      consecutiveFollowUps++;
  1176→    } else if (t.role === 'interviewer' && t.action === 'transition') {
  1177→      break;
  1178→    } else if (t.role === 'candidate') {
  1179→      continue; // skip candidate turns when counting
  1180→    }
  1181→  }
  1182→
  1183→  const prompt = `You are conducting a mock interview for a "${targetRole}" position. You have ${remainingQuestions.length} planned questions remaining.
  1184→
  1185→CONVERSATION SO FAR:
  1186→${convoText}
  1187→
  1188→${nextPlannedQuestion ? `NEXT PLANNED QUESTION (use when ready to move on): "${nextPlannedQuestion}"` : 'All planned questions covered.'}
  1189→
  1190→FOLLOW-UP COUNT on current topic: ${consecutiveFollowUps}
  1191→
  1192→YOUR TASK: Act like a real interviewer. After the candidate answers:
  1193→
  1194→1. **FOLLOW UP** if the answer is:
  1195→   - Vague or surface-level ("I worked on a project" → ask WHAT project, what was the challenge)
  1196→   - Missing specifics (no metrics, no concrete examples, no details about their role)
  1197→   - Interesting but unexplored (they mentioned something worth digging into)
  1198→   - Missing the "so what" (they described what happened but not the impact/result)
  1199→   You can ask MULTIPLE follow-ups on the same topic. Keep probing until you have real depth.
  1200→
  1201→2. **TRANSITION** to the next planned question when:
  1202→   - The candidate gave a thorough, specific answer with concrete examples
  1203→   - You've already asked 2-3 follow-ups and have sufficient depth
  1204→   - The candidate clearly has nothing more to add on this topic
  1205→
  1206→3. **WRAP UP** when: ${candidateTurnCount >= 6 ? 'You feel you have enough data (6+ exchanges completed)' : 'NOT YET — keep interviewing, only ' + candidateTurnCount + ' exchanges so far'}
  1207→
  1208→React to their answer specifically (1-2 sentences — reference something concrete they said, NOT generic filler like "Thank you for that response" or "That's helpful"). Show you actually listened. Example good reactions: "That 40% improvement in pipeline throughput is impressive — how did you measure that?" or "Interesting that you chose to refactor first rather than ship the feature." Example bad reactions: "Thank you for sharing that." or "That's great, thanks."
  1209→
  1210→Return JSON: {"reaction":"1-2 sentences referencing SPECIFIC details from their answer","action":"follow_up|challenge|transition|wrap_up","question":"your next question","score_hint":1-10,"notes":"brief note on answer quality"}`;
  1211→
  1212→  const result = await chat(prompt, {
  1213→    system: `You are Alex, an experienced ${targetRole} interviewer. You conduct interviews like a real person — curious, attentive, and thorough. You don't just read from a script. When a candidate gives a vague answer, you probe deeper. When they mention something interesting, you explore it. You ask follow-up questions naturally, like "Tell me more about that" or "What specifically was your role in that?" or "How did you measure success?" You only move to the next planned question when you're genuinely satisfied with the depth of their answer. Always return valid JSON only.`,
  1214→    maxTokens: 1024,
  1215→    subscriptionId: options.subscriptionId,
  1216→    module: 'mock_interview', feature: 'interview_turn'
  1217→  });
  1218→
  1219→  const parsed = safeParseJSON(result);
  1220→  if (parsed) return parsed;
  1221→  throw new Error('Failed to generate interview turn — could not parse LLM response');
  1222→}
