  1224→// Generate session-end feedback for a mock interview
  1225→// Returns structured format matching practice interview: content + communication + presentation
  1226→async function generateSessionFeedback(conversation, targetRole, options = {}) {
  1227→  const convoText = conversation.map(turn => {
  1228→    if (turn.role === 'interviewer') return `INTERVIEWER: ${turn.text}`;
  1229→    return `CANDIDATE: ${turn.text}`;
  1230→  }).join('\n\n');
  1231→
  1232→  // Calculate basic metrics from the text
  1233→  const candidateTurns = conversation.filter(t => t.role === 'candidate');
  1234→  const allCandidateText = candidateTurns.map(t => t.text).join(' ');
  1235→  const wordCount = allCandidateText.split(/\s+/).filter(w => w).length;
  1236→  const questionCount = conversation.filter(t => t.role === 'interviewer').length;
  1237→
  1238→  // Estimate duration from timestamps
