  1268→    "improvements": ["Specific improvement area with example", "Another improvement"],
  1269→    "covered_points": ["Key competency they demonstrated well"],
  1270→    "missed_points": ["Important area they didn't address or was weak"],
  1271→    "detailed_feedback": "2-3 paragraph deep analysis of their answer quality across ALL questions. Reference patterns: did they improve? Were some topics stronger? Did follow-ups reveal depth or gaps?",
  1272→    "specific_tips": ["Actionable tip 1", "Actionable tip 2", "Actionable tip 3"],
  1273→    "common_mistake": "The most common interview mistake they exhibited",
  1274→    "star_method_usage": { "score": 1-10, "feedback": "How well they structured answers with Situation-Task-Action-Result" },
  1275→    "technical_depth": { "score": 1-10, "feedback": "Depth of technical knowledge and specificity" }
  1276→  },
  1277→
  1278→  "communication": {
  1279→    "score": 1-10,
  1280→    "word_count": ${wordCount},
  1281→    "words_per_minute": ${wpm},
  1282→    "duration_seconds": ${durationSeconds},
  1283→    "filler_words": {"um": 0, "uh": 0, "like": 0, "you know": 0, "so": 0, "basically": 0},
  1284→    "total_fillers": 0,
  1285→    "filler_rate": 0.0,
  1286→    "pace": {
  1287→      "assessment": "good|slightly_fast|slightly_slow|too_fast|too_slow",
  1288→      "wpm": ${wpm},
  1289→      "feedback": "Assessment of their speaking pace and rhythm across the interview"
  1290→    },
  1291→    "tips": ["Speech improvement tip 1", "Tip 2"],
  1292→    "trends": "Did their communication improve/decline over the interview? More confident later? More filler words when nervous?"
  1293→  },
  1294→
  1295→  "question_scores": [
