   722→  async execute(modality, executeFn, variant = 'default', callMeta = {}) {
   723→    const callStart = Date.now();
   724→    const chain = this.getAvailableChain(modality, variant);
   725→    const triedProviders = [];
   726→
   727→    if (chain.length === 0) {
   728→      const allChain = this.getChain(modality, variant);
   729→      const reasons = allChain.map(k => {
   730→        if (!this.isProviderAvailable(k)) return `${k}: not configured`;
   731→        if (this.isCircuitOpen(k, modality)) return `${k}: circuit open`;
   732→        return `${k}: unknown`;
   733→      });
   734→      const err = new Error(`No available providers for ${modality}. ${reasons.join(', ')}`);
   735→      err.allProvidersFailed = true;
   736→      err.triedProviders = [];
   737→      err.totalElapsedMs = Date.now() - callStart;
   738→      aiCallLogger.logCall({
   739→        module: callMeta.module || 'unknown',
   740→        feature: callMeta.feature || '',
   741→        modality,
   742→        provider: 'none',
   743→        model: '',
   744→        latencyMs: Date.now() - callStart,
   745→        success: false,
   746→        errorMessage: err.message,
   747→        fallbackChain: allChain,
   748→        userId: callMeta.userId || null,
   749→      });
   750→      throw err;
   751→    }
   752→
   753→    // Per-provider timeout: 8s for TTS/ASR, 15s for LLM, 30s for vision (multi-image), 10s default
   754→    const perProviderTimeoutMs = modality === 'tts' || modality === 'asr' ? 8000
   755→      : modality === 'llm' ? 15000
   756→      : modality === 'vision' ? 30000
   757→      : 10000;
   758→
   759→    // Total cascade timeout — absolute wall-clock cap for entire fallback chain
   760→    const totalTimeoutMs = TOTAL_CASCADE_TIMEOUT[modality] || 30000;
   761→
   762→    // Number of providers to race in parallel
   763→    const raceCount = PARALLEL_RACE_COUNT[modality] || 1;
   764→
   765→    let lastError;
   766→    let failedProvider = null;
   767→
   768→    // ── Phase 1: Parallel Race (top N providers simultaneously) ──────
   769→    // Dramatically reduces latency when primary provider is slow/down.
   770→    // First success wins; if ALL raced providers fail, fall through to sequential.
   771→    if (raceCount > 1 && chain.length >= 2) {
   772→      const raceProviders = chain.slice(0, Math.min(raceCount, chain.length));
   773→
   774→      try {
   775→        const raceResult = await this._raceProviders(
   776→          raceProviders, executeFn, perProviderTimeoutMs, modality, callMeta, callStart, triedProviders
   777→        );
   778→        return raceResult;
   779→      } catch (raceErr) {
   780→        // All raced providers failed — continue with remaining providers sequentially
   781→        lastError = raceErr;
   782→        failedProvider = raceProviders[raceProviders.length - 1];
   783→        console.log(`[ai-provider] ⚡ Parallel race failed for ${modality} (${raceProviders.join(',')}), falling back to sequential`);
   784→      }
   785→    }
   786→
   787→    // ── Phase 2: Sequential Fallback (remaining providers) ───────────
   788→    // Skip providers already tried in the parallel race phase.
   789→    const sequentialStart = (raceCount > 1 && chain.length >= 2) ? Math.min(raceCount, chain.length) : 0;
   790→
   791→    for (let i = sequentialStart; i < chain.length; i++) {
   792→      const providerKey = chain[i];
   793→
   794→      // Check total cascade timeout before trying next provider
   795→      const elapsed = Date.now() - callStart;
   796→      if (elapsed >= totalTimeoutMs) {
   797→        console.warn(`[ai-provider] ⏱️ Total cascade timeout (${totalTimeoutMs}ms) hit after ${elapsed}ms — tried: ${triedProviders.join(' → ')}`);
   798→        break;
   799→      }
   800→
   801→      // Shrink per-provider timeout if we're running low on total time
   802→      const remainingMs = totalTimeoutMs - elapsed;
   803→      const effectiveTimeout = Math.min(perProviderTimeoutMs, remainingMs);
   804→
   805→      triedProviders.push(providerKey);
   806→      try {
   807→        // Wrap each provider call with a timeout to prevent hanging
   808→        const result = await Promise.race([
   809→          executeFn(providerKey),
   810→          new Promise((_, reject) => setTimeout(() => {
   811→            const err = new Error(`${providerKey} timed out after ${effectiveTimeout}ms for ${modality}`);
   812→            err.code = 'ETIMEDOUT';
   813→            reject(err);
   814→          }, effectiveTimeout))
   815→        ]);
   816→        // Log successful failover transition if we had a prior failure
   817→        if (failedProvider) {
   818→          this._logFailover(failedProvider, providerKey, modality);
   819→        }
   820→        // Extract token count if result is wrapped with _tokenCount
   821→        let tokenCount = 0;
   822→        let actualResult = result;
   823→        if (result && typeof result === 'object' && result._tokenCount !== undefined) {
   824→          tokenCount = result._tokenCount;
   825→          actualResult = result._result;
   826→        }
   827→        this.recordSuccess(providerKey, modality, tokenCount);
   828→
   829→        // Log successful call with full metadata
   830→        aiCallLogger.logCall({
   831→          module: callMeta.module || 'unknown',
   832→          feature: callMeta.feature || '',
   833→          modality,
   834→          provider: providerKey,
   835→          model: callMeta.model || this._getModelName(providerKey) || providerKey,
   836→          promptTokens: Math.round(tokenCount * 0.6),
   837→          completionTokens: Math.round(tokenCount * 0.4),
   838→          totalTokens: tokenCount,
   839→          latencyMs: Date.now() - callStart,
   840→          success: true,
   841→          fallbackChain: triedProviders.length > 1 ? triedProviders : null,
   842→          userId: callMeta.userId || null,
   843→        });
   844→
   845→        return actualResult;
   846→      } catch (err) {
   847→        lastError = err;
   848→        // Provider not applicable for this request (e.g., voice cloning TTS without audio prompt)
   849→        // Skip silently without circuit-breaking — provider is fine, just wrong for this request
   850→        if (err.notApplicable) {
   851→          continue;
   852→        }
   853→        if (this.isRetryable(err)) {
   854→          failedProvider = providerKey;
   855→          this.recordFailure(providerKey, modality, err);
   856→          // Detect geo-blocked providers and circuit-break them longer
   857→          this._checkGeoBlock(providerKey, modality, err);
   858→          continue; // try next provider
   859→        }
   860→        // Non-retryable error — log and throw
   861→        aiCallLogger.logCall({
   862→          module: callMeta.module || 'unknown',
   863→          feature: callMeta.feature || '',
   864→          modality,
   865→          provider: providerKey,
   866→          model: callMeta.model || this._getModelName(providerKey) || providerKey,
   867→          latencyMs: Date.now() - callStart,
   868→          success: false,
   869→          errorMessage: err.message,
