        duration_seconds: speechAnalysis.duration_seconds,
        filler_words: speechAnalysis.filler_words,
        total_fillers: speechAnalysis.total_fillers,
        filler_rate: speechAnalysis.filler_rate,
        pace: speechAnalysis.pace,
