      }
    };
  } catch (assemblyErr) {
    // LAST RESORT: If result assembly itself crashes, return a complete safe default
    console.error('[video-analysis] Result assembly crashed — returning safe default:', assemblyErr.message);
    const speechFallback = analyzeSpeechPatterns(finalTranscription, durationSeconds);
    return {
      overall_score: 5,
      content: {
        score: 5, strengths: ['Response provided'], improvements: ['AI analysis encountered an error — please try again'],
        covered_points: [], missed_points: [], detailed_feedback: 'Analysis could not be completed due to a temporary error.',
        improved_response: '', specific_tips: ['Try again for detailed coaching tips'],
        common_mistake: '', practice_prompt: ''
      },
      communication: {
