                {mockPastSessions.map(s => {
                  const tags = s.category_tags || ['behavioral']
                  return (
                    <Card key={s.id} className="hover:border-primary/30 transition-colors">
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
