          </div>

          {/* Conversation transcript */}
          <div className="max-h-[40vh] overflow-y-auto space-y-3 p-3 rounded-lg bg-muted/30">
            {mockSession.conversation.map((turn, i) => (
              <div key={i} className="flex gap-3">
